package sliceutil

// Sum 返回切片中所有整数之和，空切片的和为 0。
func Sum(nums []int) int {
	total := 0
	for _, n := range nums {
		total += n
	}
	return total
}

// Append 在切片末尾追加一个元素，并返回追加后的切片。
// 调用方必须用变量接住返回值，例如 nums = sliceutil.Append(nums, 6)。
func Append(nums []int, value int) []int {
	return append(nums, value)
}

package main

import (
	"fmt"

	"demo/sliceutil"
)

func main() {
	nums := []int{2, 4}
	fmt.Println("追加前长度:", len(nums))

	nums = sliceutil.Append(nums, 6)
	fmt.Println("追加后长度:", len(nums))
	fmt.Println("总和:", sliceutil.Sum(nums))

	empty := []int{}
	fmt.Println("空切片长度:", len(empty))
	fmt.Println("空切片总和:", sliceutil.Sum(empty))
}
